<?php
namespace App\Http\Controllers\Operations;use App\Http\Controllers\Controller;use App\Models\{MaintenanceRequest,Room,User};use App\Services\Operations\MaintenanceService;use Illuminate\Http\Request;
class MaintenanceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('operations.maintenance.index',['requests'=>MaintenanceRequest::with(['room','assignee'])->where('property_id',$p)->latest()->paginate(50),'rooms'=>Room::where('property_id',$p)->orderBy('room_number')->get(),'staff'=>User::where('property_id',$p)->orderBy('name')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['room_id'=>'nullable|integer','category'=>'required|string|max:60','title'=>'required|string|max:255','description'=>'nullable|string','priority'=>'required|in:low,normal,high,emergency','blocks_room'=>'nullable|boolean','assigned_to'=>'nullable|integer','due_at'=>'nullable|date','estimated_cost'=>'nullable|numeric|min:0']);if(!empty($d['room_id']))Room::where('property_id',$p)->findOrFail($d['room_id']);$m=MaintenanceRequest::create($d+['property_id'=>$p,'status'=>$d['assigned_to']?'assigned':'open','blocks_room'=>(bool)($d['blocks_room']??false),'reported_by'=>auth()->id()]);if($m->blocks_room&&$m->room)$m->room->update(['status'=>'out_of_order']);return back()->with('success','Maintenance request created.');}public function status(Request $r,MaintenanceRequest $maintenanceRequest,MaintenanceService $service){abort_unless($maintenanceRequest->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:open,assigned,in_progress,waiting_parts,resolved,closed,cancelled','assigned_to'=>'nullable|integer','due_at'=>'nullable|date','resolution_notes'=>'nullable|string','actual_cost'=>'nullable|numeric|min:0']);$service->updateStatus($maintenanceRequest,$d['status'],auth()->id(),$d['assigned_to']??null,$d['resolution_notes']??null,isset($d['actual_cost'])?(float)$d['actual_cost']:null);if(array_key_exists('due_at',$d))$maintenanceRequest->update(['due_at'=>$d['due_at']]);return back()->with('success','Maintenance request updated.');}}
